message.content:
{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "OLrmAIz5lGg71vI2WOp7zQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruin gates loom ahead.",
      "visual_description": "Crumbled stone gates choked with ivy, tattered royal banners hanging limp from twisted poles, and the glass_diver adjusting his helmet in the reflection of a puddle.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unfolds a cursed map.",
      "visual_description": "Mara spreads a parchment across a broken statue base; the ink shifts as she points; tin_fox sniffs the air nearby.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning.",
      "visual_description": "Inside a collapsed chapel, the oracle lamp sits on an altar; its flame eye glows red as it whispers of a trap in the tower.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector blocks the path.",
      "visual_description": "A figure slumped against a crumbling wall, ledger under head, stamp papers fluttering; tin_fox nudges a boot to no avail.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mirror doors reflect a false corridor.",
      "visual_description": "Tall silver doors in a dark archway; glass_diver peers into his own reflection—the reflection moves differently.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks the tower on her map.",
      "visual_description": "Mara stands on a toppled bell, shading a sketched tower; the ink glows faintly; tin_fox barks a metallic yip.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower door creaks open.",
      "visual_description": "Rusty iron door etched with winding symbols; glass_diver presses a hand to it—frost spreads from his fingers.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the tower, a spiral of whispers.",
      "visual_description": "Narrow spiral stairs with dust motes that form faces; oracle lamp swings from glass_diver's belt, casting jittery shadows.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Tin fox finds a hidden door.",
      "visual_description": "Tin_fox scratches at a section of wall that sounds hollow; Mara traces a line on her map and nods.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The tax collector sleeps on a ledger pile.",
      "visual_description": "Piled ledgers form a makeshift bed; sleeping_tax_collector snores, a stamp stuck to his cheek; a key hangs from his belt.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Glass diver reaches through a mirror.",
      "visual_description": "Frosted mirror in the tower room; glass_diver's arm vanishes into the silver surface, emerging somewhere else entirely.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Mara consults the oracle lamp.",
      "visual_description": "In a dusty library, Mara holds the lamp close; its flame whispers directions, and tin_fox listens at the door.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The armored patrol marches past.",
      "visual_description": "Hollow armor suits clank down a corridor, halberds raised; glass_diver presses flat against a alcove, holding still.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Tin fox retrieves the key from the tax collector.",
      "visual_description": "Tin_fox uses metal teeth to gently lift the key from the tax collector's belt; the sleeping figure mutters in his sleep.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The final magic door resists.",
      "visual_description": "A door of solid obsidian with a keyhole that glows; glass_diver inserts the key—the door shudders but stays shut.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The oracle lamp unlocks the door with light.",
      "visual_description": "Oracle lamp shines its eye into the keyhole; the door groans open to reveal a bridge beyond.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The rescue party crosses the bridge.",
      "visual_description": "Stone bridge spanning a misty chasm; tattered banners on both sides; glass_diver carries the lamp, Mara follows with her map, tin_fox scampers ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them.",
      "visual_description": "The bridge crumbles into the mist; on the far side, the party looks back at the ruined city; sleeping_tax_collector is still seen napping on the broken edge.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

